// Package explain implements the "explain" CLI command: print what a design
// of rule_plan.md checks, why, and how to fix what it reports.
package explain

import (
	"context"
	_ "embed" // designs.txt is generated from rule_plan.md
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/peterbourgon/ff/v4"

	"github.com/StevenACoffman/mixedmodellint/cmd/root"
	mml "github.com/StevenACoffman/mixedmodellint/internal/mixedmodellint"
)

// designs is every design block of rule_plan.md, generated by
// internal/tools/gendesigns; each starts with "=== <design ID>".
//
//go:generate go run ../../internal/tools/gendesigns -i ../../rule_plan.md -o designs.txt
//go:embed designs.txt
var designs string

// block is one design's text.
type block struct {
	id, text string
}

// Config holds the configuration for the explain command.
type Config struct {
	*root.Config
	Flags   *ff.FlagSet
	Command *ff.Command
}

// New creates and registers the explain command with the given parent config.
func New(parent *root.Config) *Config {
	var cfg Config
	cfg.Config = parent
	cfg.Flags = ff.NewFlagSet("explain").SetParent(parent.Flags)
	cfg.Command = &ff.Command{
		Name:      "explain",
		Usage:     "mixedmodellint explain DESIGN|RULE",
		ShortHelp: "show what a design checks and why",
		LongHelp: `Print a design of rule_plan.md as the plan states it: what it measures, when
it fails, the suggestion it makes and its limits. DESIGN is an ID as findings
print it, such as 7.1-B; RULE, such as 7.1, prints every design of the rule.
Each design says whether this build implements it, and at what severity.`,
		Flags: cfg.Flags,
		Exec:  cfg.exec,
	}
	parent.Command.Subcommands = append(parent.Command.Subcommands, cfg.Command)
	return &cfg
}

func (cfg *Config) exec(_ context.Context, args []string) error {
	if len(args) != 1 {
		return &root.UsageError{Err: errors.New("explain: want one design or rule, such as 7.1-B")}
	}
	blocks := lookup(designs, strings.TrimPrefix(args[0], "§"))
	if len(blocks) == 0 {
		return &root.UsageError{
			Err: fmt.Errorf("explain: no design or rule %q in rule_plan.md", args[0]),
		}
	}
	implemented := map[string]mml.DesignInfo{}
	for _, d := range mml.Designs() {
		implemented[d.ID] = d
	}
	var out strings.Builder
	for i, b := range blocks {
		if i > 0 {
			out.WriteString("\n")
		}
		status := "not implemented in this build"
		if d, ok := implemented[b.id]; ok {
			status = fmt.Sprintf("implemented; reports at %s", d.Severity)
		}
		fmt.Fprintf(&out, "%s (%s)\n%s", b.id, status, b.text)
	}
	if _, err := io.WriteString(cfg.Stdout, out.String()); err != nil {
		return fmt.Errorf("explain: %w", err)
	}
	return nil
}

// lookup returns the design whose ID is key (7.1-B), or every design of the
// rule key names (7.1), in rule_plan.md order.
func lookup(text, key string) []block {
	var out []block
	for _, part := range strings.Split(text, "=== ")[1:] {
		id, body, _ := strings.Cut(part, "\n")
		rule, _, _ := strings.Cut(id, "-")
		if id == key || rule == key {
			out = append(out, block{id: id, text: body})
		}
	}
	return out
}
